                      </div>
                    </div>
                  )}
                </>
              )}
            </div>
          )}
        </div>
      </div>

      {/* BUNDLE: COMPRADOS JUNTOS HABITUALMENTE */}
      <div className="max-w-7xl mx-auto px-4 w-full">
        <ProductBundle 
          mainProduct={{
