          </div>

          <Carousel opts={{ align: "start" }} className="w-full relative">
            <CarouselContent className="-ml-4">
              {relatedProducts.map((prod) => (
                <CarouselItem key={prod.id} className="pl-4 basis-1/2 md:basis-1/3 lg:basis-1/4">
                  <ProductCard product={prod} />
                </CarouselItem>
              ))}
            </CarouselContent>
            <div className="hidden md:flex absolute -top-14 right-12 gap-2">
              <CarouselPrevious className="relative left-0 top-0 translate-y-0 w-10 h-10 border-slate-200 bg-white" />
              <CarouselNext className="relative right-0 top-0 translate-y-0 w-10 h-10 border-slate-200 bg-white" />
            </div>
          </Carousel>
        </section>
      )}

      {/* VISTOS RECIENTEMENTE */}
      <RecentlyViewed currentProductId={product.id} />

      {/* STICKY ADD TO CART BAR (MOBILE ONLY) */}
      <div 
        className={`fixed top-20 left-0 right-0 bg-white/95 backdrop-blur-md border-b border-slate-200 p-4 z-30 transform transition-all duration-300 md:hidden flex items-center justify-between shadow-md ${
          showStickyCart ? "translate-y-0 opacity-100" : "-translate-y-full opacity-0 pointer-events-none"
        }`}
      >
        <div className="flex flex-col">
          <span className="text-sm font-bold text-slate-900 truncate max-w-[160px]">{product.name}</span>
          <span className="text-blue-600 font-black">S/ {currentPrice.toFixed(2)}</span>
        </div>
        <button 
          onClick={handleAddToCart}
          disabled={currentStock === 0}
          className="bg-blue-600 text-white font-bold px-6 py-3 rounded-xl hover:bg-blue-700 transition shadow-lg shadow-blue-200 flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isAdded ? <Check className="w-5 h-5" /> : <ShoppingCart className="w-5 h-5" />}
          {currentStock === 0 ? "Agotado" : isAdded ? "Agregado" : "Comprar"}
        </button>
      </div>

    </div>
  );
}

"use client";

import { useState, Suspense } from "react";
import { resetPassword } from "@/app/actions/auth-password";
import { toast } from "sonner";
import { useSearchParams, useRouter } from "next/navigation";
import { ArrowLeft, CheckCircle2 } from "lucide-react";

function ResetPasswordContent() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const token = searchParams.get("token");

  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!token) {
      setError("Token inválido o faltante.");
      return;
    }

    if (password !== confirmPassword) {
      setError("Las contraseñas no coinciden.");
      return;
    }

    if (password.length < 6) {
      setError("La contraseña debe tener al menos 6 caracteres.");
      return;
    }

    setLoading(true);
    setError("");
    const res = await resetPassword(token, password);
    setLoading(false);

    if (res.success) {
      setSuccess(true);
      toast.success("Contraseña actualizada con éxito.");
    } else {
      setError(res.error || "El enlace es inválido o ha expirado.");
    }
  };

  if (!token) {
    return (
      <div className="bg-slate-50 min-h-[80vh] py-16 px-4 flex justify-center items-center">
        <div className="max-w-md w-full bg-white rounded-3xl shadow-sm border border-slate-100 p-8 text-center">
          <h1 className="text-2xl font-black text-slate-900 mb-4">Enlace Inválido</h1>
          <p className="text-slate-500 mb-6">No se encontró un token de recuperación válido en la URL.</p>
          <button onClick={() => router.push("/recuperar-password")} className="bg-blue-600 text-white font-bold py-3 px-6 rounded-xl hover:bg-blue-700 transition">
            Solicitar nuevo enlace
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-slate-50 min-h-[80vh] py-16 px-4 flex justify-center items-center">
      <div className="max-w-md w-full bg-white rounded-3xl shadow-sm border border-slate-100 p-8">

        {success ? (
          <div className="text-center">
            <div className="w-16 h-16 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-6">
              <CheckCircle2 className="w-8 h-8" />
            </div>
            <h1 className="text-2xl font-black text-slate-900 mb-2">¡Contraseña actualizada!</h1>
            <p className="text-slate-500 mb-8">
              Tu contraseña ha sido cambiada exitosamente. Ya puedes iniciar sesión con tu nueva clave.
            </p>
            <button onClick={() => router.push("/mi-cuenta?login=true")} className="w-full bg-slate-900 text-white font-bold py-4 rounded-xl hover:bg-blue-600 transition">
              Ir a Iniciar Sesión
            </button>
          </div>
        ) : (
          <>
            <div className="mb-8">
              <h1 className="text-3xl font-black text-slate-900 tracking-tight">Crear nueva contraseña</h1>
              <p className="text-slate-500 mt-2">
                Ingresa tu nueva contraseña para acceder a tu cuenta.
              </p>
            </div>

            {error && (
              <div className="bg-red-50 text-red-600 p-4 rounded-xl text-sm font-medium mb-6 border border-red-100">
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit} className="flex flex-col gap-5">
              <div className="flex flex-col gap-2">
                <label className="text-sm font-bold text-slate-700">Nueva Contraseña</label>
                <input 
                  type="password" 
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full border border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white focus:border-blue-600 outline-none transition" 
                  placeholder="Mínimo 6 caracteres"
                  required 
                />
              </div>

              <div className="flex flex-col gap-2">
                <label className="text-sm font-bold text-slate-700">Confirmar Contraseña</label>
                <input 
                  type="password" 
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className="w-full border border-slate-200 rounded-xl px-4 py-3 bg-slate-50 focus:bg-white focus:border-blue-600 outline-none transition" 
                  placeholder="Repite la contraseña"
                  required 
                />
              </div>

              <button 
                type="submit" 
                disabled={loading}
                className="w-full bg-slate-900 text-white font-bold py-4 rounded-xl mt-4 hover:bg-blue-600 transition disabled:opacity-50"
              >
                {loading ? "Guardando..." : "Guardar contraseña"}
              </button>
            </form>
          </>
        )}

      </div>
    </div>
  );
}

export default function ResetPasswordPage() {
  return (
    <Suspense fallback={<div className="min-h-[80vh] flex items-center justify-center">Cargando...</div>}>
      <ResetPasswordContent />
    </Suspense>
  );
}

import ProductCard from "@/components/ui/ProductCard";
import type { Product } from "@/lib/data";
import { getPaginatedProducts } from "@/lib/api/products";
import { getCachedCategories } from "@/lib/api/categories";
import { getCachedBrands } from "@/lib/api/brands";
import CatalogSidebar from "@/components/shop/CatalogSidebar";
import CatalogSort from "@/components/shop/CatalogSort";
import Link from "next/link";
import PaginationControls from "@/components/shop/PaginationControls";
import RecentlyViewed from "@/components/shop/RecentlyViewed";

export const dynamic = 'force-dynamic';

export default async function TiendaPage(props: { searchParams: Promise<{ [key: string]: string | string[] | undefined }> }) {
  const searchParams = await props.searchParams;

  // Extraemos y validamos los parámetros de la URL
  const marca = typeof searchParams.marca === 'string' ? searchParams.marca : undefined;
  const categoria = typeof searchParams.categoria === 'string' ? searchParams.categoria : undefined;
  const sort = typeof searchParams.sort === 'string' ? searchParams.sort : undefined;
  const minPrice = typeof searchParams.minPrice === 'string' ? Number(searchParams.minPrice) : undefined;
  const maxPrice = typeof searchParams.maxPrice === 'string' ? Number(searchParams.maxPrice) : undefined;
  const q = typeof searchParams.q === 'string' ? searchParams.q : undefined;
  const inStock = searchParams.inStock === 'true';
  const hasDiscount = searchParams.hasDiscount === 'true';
  const page = typeof searchParams.page === 'string' ? Number(searchParams.page) : 1;

  // 1. Ejecutar llamadas a la base de datos en paralelo
  const [paginatedData, categories, brands] = await Promise.all([
    getPaginatedProducts({ 
      categorySlug: categoria,
      brandSlug: marca,
      sort,
      minPrice,
      maxPrice,
      query: q,
      inStock,
      hasDiscount,
      page,
      pageSize: 12
    }),
    getCachedCategories(),
    getCachedBrands()
  ]);

  console.log(`[DIAGNOSTIC] Tienda requested with category: "${categoria}". Products found: ${paginatedData.products.length}`);


  const allProducts = paginatedData.products;

  // Encontrar el nombre real de la categoría seleccionada y su padre
  let currentCategoryName = "";
  let parentCategoryName = "";

  if (categoria) {
    for (const parent of categories) {
      if (parent.slug === categoria) {
        currentCategoryName = parent.name;
        break;
      }
      if (parent.children) {
        const child = parent.children.find((c: any) => c.slug === categoria);
        if (child) {
          currentCategoryName = child.name;
          parentCategoryName = parent.name;
          break;
        }
      }
    }
  }

  // Encontrar nombre de la marca si hay solo 1 seleccionada
  let currentBrandName = "";
  if (marca && !marca.includes(",")) {
    const b = brands.find((b: any) => b.slug === marca);
    if (b) currentBrandName = b.name;
  }

  return (
    <div className="flex flex-col min-h-screen bg-white">

      {/* BREADCRUMBS DINÁMICAS */}
      <div className="bg-slate-50 border-b border-slate-100 py-4">
        <div className="max-w-7xl mx-auto px-4 w-full">
          <p className="text-sm text-slate-500 font-medium">
            <Link href="/" className="hover:text-blue-600 transition">Inicio</Link> 
            <span className="mx-2">/</span> 
            <Link href="/tienda" className="hover:text-blue-600 transition">Tienda</Link>

            {parentCategoryName && (
              <>
                <span className="mx-2">/</span> 
                <span className="text-slate-500">{parentCategoryName}</span>
              </>
            )}

            {currentCategoryName && (
              <>
                <span className="mx-2">/</span> 
                <span className="text-slate-900 font-bold">{currentCategoryName}</span>
              </>
            )}

            {!currentCategoryName && currentBrandName && (
               <>
                 <span className="mx-2">/</span> 
                 <span className="text-slate-900 font-bold">{currentBrandName}</span>
               </>
            )}
          </p>
        </div>
      </div>

      {/* CONTENIDO PRINCIPAL */}
      <div className="max-w-7xl mx-auto px-4 w-full py-12 flex flex-col md:flex-row gap-8">

        {/* COLUMNA IZQUIERDA (25% - Sidebar Filtros Funcional) */}
        <CatalogSidebar categories={categories} brands={brands} />

        {/* COLUMNA DERECHA (75% - Grid Productos) */}
        <div className="flex-1 flex flex-col min-w-0">

          <div className="mb-8">
            <h1 className="text-4xl font-black text-slate-900 tracking-tight mb-4 capitalize">
              {q ? `Resultados para "${q}"` : 
               currentCategoryName ? currentCategoryName : 
               currentBrandName ? `Productos ${currentBrandName}` : 
               `Todo el Catálogo`}
            </h1>

            {/* Componente Cliente para Ordenamiento */}
            <CatalogSort totalResults={paginatedData.totalCount} />
          </div>

          {allProducts.length > 0 ? (
            <>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-12">
                {allProducts.map((product) => (
                  <ProductCard key={product.id} product={product} />
                ))}
              </div>
              <PaginationControls 
                currentPage={paginatedData.currentPage} 
                totalPages={paginatedData.totalPages} 
              />
            </>
          ) : (
            <div className="flex flex-col items-center justify-center py-20 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
              <span className="text-4xl mb-4">🔍</span>
              <h3 className="text-xl font-bold text-slate-800 mb-2">No se encontraron productos</h3>
              <p className="text-slate-500 text-center max-w-md">
                Intenta ajustar los filtros de precio o selecciona una categoría diferente para ver más resultados.
              </p>
              <Link href="/tienda" className="mt-6 bg-blue-600 text-white font-bold px-6 py-3 rounded-full hover:bg-blue-700 transition">
                Limpiar Filtros
              </Link>
            </div>
          )}

        </div>
      </div>

      {/* VISTOS RECIENTEMENTE (Global en tienda) */}
      <RecentlyViewed />
    </div>
  );
}
